import React, { useState, useEffect, useCallback } from 'react';
import './Calculator.css';
import { evaluate } from 'mathjs';

function Calculator() {
  const [input, setInput] = useState('');
  const [result, setResult] = useState('');

  const handleCalculate = useCallback(() => {
    try {
      const calculatedResult = evaluate(input);
      setResult(String(calculatedResult));
      setInput('');
    } catch (error) {
      setResult('Error');
      setTimeout(() => setResult(''), 1000);
    }
  }, [input]);

  // Handle keyboard input
  useEffect(() => {
    const handleKeyPress = (e) => {
      if ((e.key >= '0' && e.key <= '9') || '+-*/.'.includes(e.key)) {
        handleButtonClick(e.key);
      } else if (e.key === 'Enter') {
        handleCalculate();
      } else if (e.key === 'Escape') {
        handleClear();
      } else if (e.key === 'Backspace') {
        handleDelete();
      }
    };

    window.addEventListener('keydown', handleKeyPress);
    return () => window.removeEventListener('keydown', handleKeyPress);
  }, [handleCalculate]);

  const handleButtonClick = (value) => {
    setInput(prev => prev + value);
  };

  const handleClear = () => {
    setInput('');
    setResult('');
  };

  const handleDelete = () => {
    setInput(prev => prev.slice(0, -1));
  };

  const handleScientificOperation = (operation) => {
    try {
      let value;
      switch(operation) {
        case 'sin':
          value = Math.sin(evaluate(input) * Math.PI / 180);
          break;
        case 'cos':
          value = Math.cos(evaluate(input) * Math.PI / 180);
          break;
        case 'tan':
          value = Math.tan(evaluate(input) * Math.PI / 180);
          break;
        case 'sqrt':
          value = Math.sqrt(evaluate(input));
          break;
        case 'square':
          value = Math.pow(evaluate(input), 2);
          break;
        case 'log':
          value = Math.log10(evaluate(input));
          break;
        case 'ln':
          value = Math.log(evaluate(input));
          break;
        default:
          value = 0;
      }
      setResult(String(Number(value.toFixed(8))));
      setInput('');
    } catch (error) {
      setResult('Error');
      setTimeout(() => setResult(''), 1000);
    }
  };

  return (
    <div className="calculator">
      <div className="display">{result || input || '0'}</div>
      <div className="buttons">
        <button onClick={() => handleScientificOperation('sin')}>sin</button>
        <button onClick={() => handleScientificOperation('cos')}>cos</button>
        <button onClick={() => handleScientificOperation('tan')}>tan</button>
        <button onClick={() => handleButtonClick('+')}>+</button>
        <button onClick={() => handleScientificOperation('sqrt')}>√</button>
        <button onClick={() => handleScientificOperation('square')}>x²</button>
        <button onClick={() => handleScientificOperation('log')}>log</button>
        <button onClick={() => handleButtonClick('-')}>-</button>
        <button onClick={() => handleButtonClick('7')}>7</button>
        <button onClick={() => handleButtonClick('8')}>8</button>
        <button onClick={() => handleButtonClick('9')}>9</button>
        <button onClick={() => handleButtonClick('*')}>*</button>
        <button onClick={() => handleButtonClick('4')}>4</button>
        <button onClick={() => handleButtonClick('5')}>5</button>
        <button onClick={() => handleButtonClick('6')}>6</button>
        <button onClick={() => handleButtonClick('/')}>/</button>
        <button onClick={() => handleButtonClick('1')}>1</button>
        <button onClick={() => handleButtonClick('2')}>2</button>
        <button onClick={() => handleButtonClick('3')}>3</button>
        <button onClick={handleClear}>C</button>
        <button onClick={() => handleButtonClick('0')}>0</button>
        <button onClick={() => handleButtonClick('.')}>.</button>
        <button onClick={handleDelete}>⌫</button>
        <button onClick={handleCalculate}>=</button>
      </div>
    </div>
  );
}

export default Calculator;